{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/publication.py; cloud_pilot/live/http.py",
      "detail": "Publication recovery attempts to write its invalidation record under daily/.../qa/, but the inherited put_immutable method accepts only cloud_pilot/live_artifacts/ paths. The real recovery path therefore raises ARTIFACT_PATH before invalidation or fence release. The regression test uses a fake transport that does not enforce this restriction.",
      "required_fix": "Add a narrowly scoped, immutable canonical QA writer and test recovery through the real transport path constraints, including expired evidence and a subsequent research epoch."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/engine.py; cloud_pilot/multilingual/publication.py",
      "detail": "A source retrieval or archive failure produces only a generic halt. Successfully collected partial evidence, the failed source, blocked facts and a canonical research verdict are not persisted, so the required research handoff is missing.",
      "required_fix": "Persist a non-writing-ready research failure with the available source log, access failure, blocked facts and handoff before stopping. Test failure at each source position."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/stages.py; cloud_pilot/multilingual/publication.py",
      "detail": "check_research rejects every non-ready result before validating its verdict, and persist_failed_research unconditionally changes the result to RESEARCH_FAIL. A valid non-ready RESEARCH_CONDITIONAL verdict is therefore misreported as FAIL, and malformed responses can lack the required blocked-fact fields.",
      "required_fix": "Validate and persist PASS, CONDITIONAL and FAIL separately, preserving legitimate non-ready conditional status and its boundaries. For malformed output, create an explicitly incomplete failure record with the missing fields and no writing readiness."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/publication.py; cloud_pilot/multilingual/research_contract.py; cloud_pilot/multilingual/sources.py",
      "detail": "The canonical handoff and source log omit mandatory publish-grade fields. In particular, source rows do not record source titles or supported facts, while HANDOFF.json lacks required allowed/blocked facts, source counts and scope status. Those values being partly available in other packet files does not make the handoff complete.",
      "required_fix": "Build and validate the complete per-package handoff and source log from directly supported evidence, including titles, supported facts, source counts, scope, allowed and blocked facts, confidence and applicable identity fields."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/startup.py; cloud_pilot/live/engine.py; cloud_pilot/multilingual/publication.py",
      "detail": "The startup synchronization is recorded only in the operational journal, not in the Daily Manifest or RESEARCH_READY startup block as required. After research completes, the active path starts writing without the prescribed writing-stage pull and pre-writing startup checklist.",
      "required_fix": "Record actual startup identifiers in the canonical batch artifact and perform and document the required writing-stage synchronization and checklist against the completed research baseline before any writing call."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
